package net.shiroha233.roadweaver.planning.impl;

import java.util.List;
import java.util.concurrent.CancellationException;
import net.minecraft.core.BlockPos;

/** 对生产plan注入取消/采样失败，核实是否仍返回看似正常的连线。 */
public final class PipelineFailureProbe {
    public static void main(String[] args) {
        for (boolean cancellation : new boolean[]{false, true}) {
            var planner = new PipelinePlanner(8, () -> {
                if (cancellation) throw new CancellationException("probe-cancel");
                throw new IllegalStateException("probe-sample-failed");
            });
            var result = planner.plan(List.of(new BlockPos(0, 64, 0), new BlockPos(24, 64, 0)), 48);
            System.out.println("PIPELINE_FAILURE cancellation=" + cancellation + " returnedConnections="
                    + result.size() + " status=" + result.getFirst().status());
            if (result.size() != 1) throw new AssertionError("源码行为已经变化");
        }
    }
}
